package org.freecad.mobilelab;
/** Shared GLES shaders, exercised by a real pbuffer regression. */
final class Shaders {
 static final String VERTEX = "#version 300 es\nlayout(location=0) in vec3 position;layout(location=1) in vec3 normal;layout(location=2) in vec4 color;layout(location=3) in vec2 material;uniform mat4 mvp;uniform mat4 mv;out vec3 n;out vec3 p;out vec4 c;out vec2 mat;out float wz;void main(){gl_Position=mvp*vec4(position,1.0);n=mat3(mv)*normal;p=(mv*vec4(position,1.0)).xyz;c=color;mat=material;wz=position.z;}";
 static final String FRAGMENT = "#version 300 es\nprecision highp float;in vec3 n;in vec3 p;in vec4 c;in vec2 mat;in float wz;uniform bool unlit;uniform int style;uniform bool clipping;uniform float clipZ;out vec4 result;\nvoid main(){if(clipping&&wz>clipZ)discard;if(unlit){result=c;return;}vec3 nn=normalize(n);if(!gl_FrontFacing)nn=-nn;vec3 l=normalize(vec3(0.3,0.7,1.0)),eye=normalize(-p);float nl=max(dot(nn,l),0.0);float fill=max(dot(nn,normalize(vec3(-0.8,-0.2,0.6))),0.0);\nif(style==2){float bands=sin(atan(nn.x,nn.z)*18.0+nn.y*10.0);result=vec4(vec3(bands>0.0?0.94:0.06),1.0);return;}\nif(style==1){float rough=clamp(mat.x,0.04,1.0),metal=clamp(mat.y,0.0,1.0);vec3 base=pow(clamp(c.rgb,0.0,1.0),vec3(2.2)),h=normalize(l+eye);float nv=max(0.001,dot(nn,eye)),nh=max(0.0,dot(nn,h)),vh=max(0.0,dot(eye,h)),a=rough*rough,a2=a*a,d=nh*nh*(a2-1.0)+1.0,D=a2/(3.14159265*d*d),k=(rough+1.0)*(rough+1.0)/8.0,G=nv/(nv*(1.0-k)+k)*nl/(nl*(1.0-k)+k);vec3 f0=mix(vec3(0.04),base,metal),F=f0+(vec3(1.0)-f0)*pow(1.0-vh,5.0),spec=D*G*F/max(0.001,4.0*nv*nl),diff=(vec3(1.0)-F)*(1.0-metal)*base/3.14159265,light=3.0*(diff+spec)*nl+base*(0.15+0.18*fill)+f0*0.15;result=vec4(pow(light/(vec3(1.0)+light),vec3(1.0/2.2)),1.0);return;}\nfloat spec=pow(max(dot(nn,normalize(l+eye)),0.0),48.0);result=vec4(c.rgb*(0.28+0.64*nl+0.18*fill)+vec3(0.24)*spec,1.0);}";
}
